<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Policy\Allow;

use Throwable;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Create\DcrInitialAccessTokenCreateAllowDecision;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Update\DcrInitialAccessTokenUpdateAllowDecision;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\List\DcrInitialAccessTokenListAllowDecision;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Retrieve\DcrInitialAccessTokenRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Delete\DcrInitialAccessTokenDeleteAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\AllowDecision;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TenantAdminAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function checkCreate(DcrInitialAccessTokenCreateAllowDecision $proposal): AllowDecision
    {
        return $this->check('DcrInitialAccessTokenCreateAllowDecision', $proposal);
    }
    public function checkUpdate(DcrInitialAccessTokenUpdateAllowDecision $proposal): AllowDecision
    {
        return $this->check('DcrInitialAccessTokenUpdateAllowDecision', $proposal);
    }
    public function checkList(DcrInitialAccessTokenListAllowDecision $proposal): AllowDecision
    {
        return $this->check('DcrInitialAccessTokenListAllowDecision', $proposal);
    }
    public function checkRetrieve(DcrInitialAccessTokenRetrieveAllowDecision $proposal): AllowDecision
    {
        return $this->check('DcrInitialAccessTokenRetrieveAllowDecision', $proposal);
    }
    public function checkDelete(DcrInitialAccessTokenDeleteAllowDecision $proposal): AllowDecision
    {
        return $this->check('DcrInitialAccessTokenDeleteAllowDecision', $proposal);
    }
    private function check(string $name, AllowDecision $proposal): AllowDecision
    {
        $this->logDebug("Check " . $name . " on TenantAdminAllow Dcr initial access token");
        $span = $this->startSpan("Check " . $name . " on TenantAdminAllow Dcr initial access token");
        try {
            $identity = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (!$identity->hasRole("admin")) {
                    $proposal->deny('Disabled if not TenantAdmin');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
